import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, smoothstep, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DoubleSide, Color } = ctx.THREE;

  const group = new Group();
  const inner = new Group();
  group.add(inner);

  const specColors = config.intent?.visualSpec?.colors ?? {};
  const ink = specColors.ink ?? '#16161d';
  const paper = specColors.paper ?? '#e8ecf2';
  const accent = specColors.accent ?? '#ff2a38';
  const surface = specColors.surface ?? '#0b0b10';

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const w = 1.6, h = 0.48;

  // --- Engineered vertical gradient backdrop ---
  const cTop = uniform(new Color(surface));
  const cBot = uniform(new Color(ink));
  const gradT = smoothstep(0.0, 1.0, uv().y);

  const backdropGeo = new PlaneGeometry(w, h);
  const backdropMat = new MeshBasicNodeMaterial({ transparent: true, side: DoubleSide });
  backdropMat.colorNode = mix(cTop, cBot, gradT);

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -0.02;
  inner.add(backdrop);

  // --- Image overlay (subtle surface grain) ---
  const overlayGeo = new PlaneGeometry(w, h);
  const overlayMat = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.08,
    side: DoubleSide,
  });
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      overlayMat.map = tex;
      overlayMat.needsUpdate = true;
    });
  }
  const overlay = new Mesh(overlayGeo, overlayMat);
  overlay.position.z = -0.008;
  inner.add(overlay);

  // --- Thin machined accent line ---
  const accentGeo = new PlaneGeometry(0.22, 0.01);
  const accentMat = new MeshBasicNodeMaterial({ color: accent, transparent: true });
  const accentLine = new Mesh(accentGeo, accentMat);
  accentLine.position.set(0, -h * 0.26, 0.01);
  inner.add(accentLine);

  // --- Text ---
  for (const item of items) {
    const fontSize = item.typography?.fontSize ?? 39;
    const textObj = ctx.fontAtlas.createText(item.text, {
      fontSize: fontSize,
      color: paper,
      align: 'center',
    });
    textObj.position.set(0, 0.04, 0.02);
    inner.add(textObj);
  }

  // --- Entrance: weighted-settle ---
  const tl = gsap.timeline();
  tl.from(inner.position, { z: 0.3, duration: 0.6, ease: 'power3.out' });
  tl.from(inner.scale, { x: 0.93, y: 0.93, z: 0.93, duration: 0.7, ease: 'power4.out' }, 0);
  tl.to(inner.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.4, ease: 'power2.out' }, 0.55);
  tl.to(inner.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.5, ease: 'power4.out' });

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    tl.kill();
    backdropGeo.dispose();
    backdropMat.dispose();
    overlayGeo.dispose();
    overlayMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
  };

  return group;
}
